package com.ultras.bans.service;
import com.ultras.bans.ULTRASBansPlugin; import com.ultras.bans.model.PunishmentType; import org.bukkit.Bukkit; import org.bukkit.entity.Player;
public final class NetworkEnforcer {private final ULTRASBansPlugin p;public NetworkEnforcer(ULTRASBansPlugin p){this.p=p;}public void tick(){for(Player x:Bukkit.getOnlinePlayers()){p.database().active(x.getUniqueId(),PunishmentType.BAN).thenAccept(a->{if(a.isPresent())Bukkit.getScheduler().runTask(p,()->x.kick(com.ultras.bans.utility.Text.c("<red>ᴜʟᴛʀᴀs</red> | Your ban is active.")));});p.database().active(x.getUniqueId(),PunishmentType.FREEZE).thenAccept(a->{if(a.isPresent())Bukkit.getScheduler().runTask(p,()->p.freeze().set(x,true));});p.database().active(x.getUniqueId(),PunishmentType.JAIL).thenAccept(a->{if(a.isPresent())Bukkit.getScheduler().runTask(p,()->p.jail().set(x,true));});}}}
